      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Classes\n  DotsHoverMoveDefaultStyles\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            libs/viz-components/src/lib/dots/events/actions/dots-hover-move-actions.ts\n        \n\n\n\n\n            \n                Implements\n            \n            \n                            HoverMoveAction\n            \n\n\n            \n    Index\n    \n        \n\n                \n                    \n                        Methods\n                    \n                \n                \n                    \n                        \n                            \n                                onEnd\n                            \n                            \n                                onStart\n                            \n                        \n                    \n                \n\n\n\n\n\n        \n    \n\n\n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                        onEnd\n                        \n                    \n                \n            \n            \n                \nonEnd(host: DotsHost)\n                \n            \n\n\n                    \n                        \n                            Defined in libs/viz-components/src/lib/dots/events/actions/dots-hover-move-actions.ts:20\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                        \n                                    \n                                    \n                                        \n                                                host\n                                            \n                                                            DotsHost\n                                            \n\n                                            \n                                                    No\n                                            \n\n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :         void\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n    \n        \n            \n                \n                    \n                    \n                        onStart\n                        \n                    \n                \n            \n            \n                \nonStart(host: DotsHost)\n                \n            \n\n\n                    \n                        \n                            Defined in libs/viz-components/src/lib/dots/events/actions/dots-hover-move-actions.ts:7\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                        \n                                    \n                                    \n                                        \n                                                host\n                                            \n                                                            DotsHost\n                                            \n\n                                            \n                                                    No\n                                            \n\n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :         void\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n\n\n\n\n\n\n    \n\n\n    \n        import { EventType, HoverMoveAction } from '../../../events';\nimport { DotsHost } from '../dots-events.directive';\n\nexport class DotsHoverMoveDefaultStyles\n  implements HoverMoveAction>\n{\n  onStart(host: DotsHost): void {\n    host.marks.dotGroups\n      .filter((d) => d.index !== host.getDotDatum().index)\n      .selectAll('circle')\n      .style('fill', '#ccc');\n\n    host.marks.dotGroups\n      .filter((d) => d.index === host.getDotDatum().index)\n      .selectAll('circle')\n      .select((d, i, nodes) => nodes[i].parentElement)\n      .raise();\n  }\n\n  onEnd(host: DotsHost): void {\n    host.marks.dotGroups\n      .selectAll('circle')\n      .style('fill', null);\n  }\n}\n\nexport class DotsHoverMoveEmitTooltipData\n  implements HoverMoveAction>\n{\n  onStart(host: DotsHost): void {\n    const output = host.getInteractionOutput(EventType.HoverMove);\n    host.emitInteractionOutput(output);\n  }\n\n  onEnd(host: DotsHost): void {\n    host.emitInteractionOutput(null);\n  }\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
